inserted as (
  insert into public.bajas (
    num_empleado,
    nombre,
    area,
    seccion,
    puesto,
    fecha_ingreso,
    fecha_baja,
    tipo_baja,
    motivo_baja,
    created_at
  )
  select
    num_empleado,
    nombre,
    area,
    seccion,
    puesto,
    fecha_ingreso,
    fecha_baja,
    null,
    null,
    '2026-09-02T22:28:28.8268264Z'::timestamptz
  from import_bajas_historicas
  on conflict (num_empleado) do nothing
  returning num_empleado
)
select
  468 as filas_fuente,
  467 as filas_validas,
  count(*) as filas_insertadas,
  467 - count(*) as filas_ya_existentes,
  1 as filas_excluidas
from inserted;

